// Standalone page orchestration: take a file, run the pipeline, render every
// section from the resulting report. Nothing leaves the browser. The pipeline
// and the renderers are shared with the blog embed (embed.js).
import { h, fmtBytes } from "./render/h.js";
import { renderVerdict } from "./render/verdict.js";
import { renderFileMap } from "./render/fileMap.js";
import { renderByteMap } from "./render/byteMap.js";
import { renderHashTree } from "./render/hashTree.js";
import { renderBoxAnatomy, renderTimestamps } from "./render/boxDetail.js";
import { renderCertChain } from "./render/certChain.js";
import { renderMedia, displayableUrl } from "./render/media.js";
import { analyse, errorReport, fetchPhoto } from "./pipeline.js";

const $ = (s) => document.querySelector(s);
const results = $("#results");
const status = $("#status");
const drop = $("#drop");
const input = $("#file");
const verdictSlot = $("#verdict");
const veil = $("#dropveil");
let previewUrls = [];
let mediaGeneration = 0;

function setStatus(text, busy = true) {
  status.textContent = text;
  status.classList.toggle("busy", busy);
  status.hidden = !text;
}

function showChecking(file, step) {
  verdictSlot.replaceChildren(
    h("p.checking", `${step} ${file.name} (${fmtBytes(file.size)})…`),
  );
  verdictSlot.hidden = false;
}

async function handleFile(file) {
  results.hidden = true;
  results.replaceChildren();
  previewUrls.forEach((u) => URL.revokeObjectURL(u));
  previewUrls = [];
  setStatus("", false);
  try {
    const { report, processedJpeg, ms } = await analyse(file, (step) =>
      showChecking(file, step),
    );
    render(report, processedJpeg, file, ms);
  } catch (e) {
    console.error("Analysis failed", e);
    render(errorReport(file, `Unexpected error: ${e.message || e}`));
  }
}

function section(id, title, lead, body) {
  return h(
    `section.card#${id}`,
    h("h2", title),
    lead && h("p.lead", lead),
    body,
  );
}

// Object URLs for the photo and the reference image it carries.
function mediaSources(processed, file) {
  const generation = ++mediaGeneration;
  const track = (u) => (previewUrls.push(u), u);
  return {
    outer: displayableUrl(file, track, () => generation === mediaGeneration),
    inner: processed
      ? track(
          URL.createObjectURL(new Blob([processed], { type: "image/jpeg" })),
        )
      : null,
  };
}

function render(report, processed, file, ms) {
  const v = report.verdict.status;
  const card = renderVerdict(report);
  verdictSlot.replaceChildren(
    ...(report.file.container
      ? [
          section(
            "images",
            processed ? "1. Photo and reference image" : "Photo",
            null,
            renderMedia({ ...mediaSources(processed, file), certified: v === "pass" }),
          ),
        ]
      : []),
    card,
  );
  verdictSlot.hidden = false;
  if (v === "error" && !report.file.container) {
    return;
  }
  const nodes = [];
  if (report.carrier && report.processed) {
    nodes.push(
      section(
        "where",
        "2. Where the reference image is stored",
        "The embedded reference image is a JPEG. In a HEIC file it is stored as a separate item; in a JPEG export it is split across metadata segments.",
        renderFileMap(report),
      ),
      section(
        "bytes",
        "3. Which bytes are signed",
        "The inner JPEG is split into three ranges. Each is hashed separately with SHA-512; only the signature itself is cut out.",
        h(
          "div",
          renderByteMap(report),
          h(
            "details.signature-details",
            h("summary", "Signature box and timestamps"),
            h(
              "p",
              "The signature box contains the signature, certificates and development time. Everything except the signature bytes is included in the hash.",
            ),
            renderBoxAnatomy(report),
            h("h3", "Timestamps"),
            renderTimestamps(report),
          ),
        ),
      ),
      section(
        "tree",
        "4. Checking the signature",
        "The three digests are concatenated and hashed again. That 64-byte value is wrapped the IETF composite way and signed twice: once post-quantum, once classical.",
        renderHashTree(report),
      ),
      section(
        "certs",
        "5. Who signed the reference image",
        "The signer certificate chains to the Apple Prove root, whose public key is pinned in this tool.",
        renderCertChain(report),
      ),
    );
  } else if (v === "not-reference-image" && report.file) {
    nodes.push(
      section(
        "where",
        "What was found",
        null,
        h(
          "ul",
          h("li", `Container: ${report.file.container}`),
          report.file.width &&
            h("li", `${report.file.width} × ${report.file.height} px`),
          report.file.exif?.model &&
            h("li", `Camera: ${report.file.exif.model}`),
          h(
            "li",
            report.file.exif?.appleReferenceFlag != null
              ? `Apple MakerNote 0x0063 = ${report.file.exif.appleReferenceFlag}`
              : "No Apple MakerNote Reference Image flag",
          ),
        ),
      ),
    );
  }
  nodes.push(
    h(
      "p.muted.small",
      `Analysed ${report.file.name ?? "file"} in ${ms} ms, entirely in this browser. `,
      h(
        "a",
        {
          href: "#",
          onclick: (e) => {
            e.preventDefault();
            downloadReport(report);
          },
        },
        "Download report.json",
      ),
    ),
  );
  results.replaceChildren(...nodes);
  results.hidden = false;
}

function downloadReport(report) {
  const url = URL.createObjectURL(
    new Blob([JSON.stringify(report, null, 2)], { type: "application/json" }),
  );
  const a = h("a", {
    href: url,
    download: `${(report.file.name || "photo").replace(/\.[^.]+$/, "")}.report.json`,
  });
  document.body.append(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

// --- wiring ---
input.addEventListener(
  "change",
  () => input.files[0] && handleFile(input.files[0]),
);
// The whole page is a drop target. dragenter/dragleave fire for every child
// element crossed, so keep a depth counter instead of toggling on each event.
let dragDepth = 0;
const hasFiles = (e) => [...(e.dataTransfer?.types || [])].includes("Files");
const setDragging = (on) => {
  dragDepth = on ? dragDepth : 0;
  veil.hidden = !on;
  drop.classList.toggle("over", on);
};
window.addEventListener("dragenter", (e) => {
  if (!hasFiles(e)) return;
  e.preventDefault();
  dragDepth++;
  setDragging(true);
});
window.addEventListener("dragover", (e) => {
  if (!hasFiles(e)) return;
  e.preventDefault();
  e.dataTransfer.dropEffect = "copy";
});
window.addEventListener("dragleave", (e) => {
  if (!hasFiles(e)) return;
  if (--dragDepth <= 0) setDragging(false);
});
window.addEventListener("drop", (e) => {
  e.preventDefault();
  setDragging(false);
  const f = e.dataTransfer?.files?.[0];
  if (f) handleFile(f);
});
drop.addEventListener("click", (e) => {
  if (e.target.closest("button, label, a")) return;
  input.click();
});
const loadExample = async () => {
  setStatus("Fetching the example photo (8 MB)…");
  try {
    await handleFile(
      await fetchPhoto("assets/samples/IMG_0071.JPG", "IMG_0071.JPG"),
    );
  } catch (e) {
    setStatus(`Could not load the example: ${e.message}`, false);
  }
};
$("#example").addEventListener("click", loadExample);
window.addEventListener("paste", (e) => {
  const f = [...(e.clipboardData?.files || [])][0];
  if (f) handleFile(f);
});
